"use client";

import React, { useEffect } from "react";
import Link from "next/link";
import { usePathname } from "next/navigation";
import { useChatStore } from "@/lib/store/chat";
// Nếu bạn dùng Clerk, giữ lại 4 import sau; nếu không dùng, xóa đi:
// import { SignInButton, SignUpButton, SignedIn, SignedOut, UserButton } from "@clerk/nextjs";

interface NavbarMenuProps {
  isMenuOpen: boolean;
  onMenuClick: () => void;
  onClose: () => void;
  historyItems: Array<{ name: string; href: string }>;
}

const NavbarMenu: React.FC<NavbarMenuProps> = ({
  isMenuOpen,
  onMenuClick,
  onClose,
  historyItems,
}) => {
  const pathname = usePathname();
  const onStatistics = pathname?.startsWith("/statistics");
  const clearMessages = useChatStore((s) => s.clearMessages);

  // Đóng menu bằng ESC
  useEffect(() => {
    const onEsc = (e: KeyboardEvent) => {
      if (e.key === "Escape" && isMenuOpen) onClose();
    };
    window.addEventListener("keydown", onEsc);
    return () => window.removeEventListener("keydown", onEsc);
  }, [isMenuOpen, onClose]);

  return (
    <nav className="bg-[#BBDCE5] text-white shadow-lg fixed top-0 left-0 right-0 z-[100] h-16">
      <div className="flex items-center justify-between px-4 h-full max-w-7xl mx-auto">
        {/* Trái */}
        <div className="flex items-center gap-2">
          <button
            onClick={onMenuClick}
            className={`p-2 rounded-md text-xl transition-colors duration-150 ${
              isMenuOpen ? "opacity-0 pointer-events-none" : "hover:bg-[#D0E8F2]"
            }`}
            aria-label="Mở menu"
          >
            ☰
          </button>

          {onStatistics && (
            <Link
              href="/"
              className="ml-2 px-3 py-2 rounded-md bg-white/20 hover:bg-white/40 text-sm md:text-base"
            >
              ← Trang chủ
            </Link>
          )}
        </div>

        {/* Tiêu đề */}
        <h1 className="text-lg font-bold whitespace-nowrap">Ask Them All</h1>

        {/* Phải */}
        <div className="flex items-center gap-2">
          {/* Nút Đoạn chat mới – chỉ reset FRONTEND store */}
          <button
            onClick={() => {
              if (window.confirm("Bắt đầu đoạn chat mới?")) {
                clearMessages();
              }
            }}
            className="px-3 py-1 rounded-lg bg-white/20 hover:bg-white/30 text-sm"
          >
            Đoạn chat mới
          </button>

          {/* Nếu có Clerk thì bật lại khối bên dưới */}
          {/*
          <SignedOut>
            <SignInButton />
            <SignUpButton>
              <button className="bg-[#456268] rounded-full text-sm sm:text-base h-10 sm:h-12 px-4 sm:px-5">
                Sign Up
              </button>
            </SignUpButton>
          </SignedOut>
          <SignedIn>
            <UserButton />
          </SignedIn>
          */}
        </div>
      </div>

      {/* Overlay + Side menu (nếu bạn có) */}
      {isMenuOpen && (
        <>
          <div
            className="fixed inset-0 bg-black/40 z-[90]"
            onClick={onClose}
          />
          <div className="fixed top-16 left-0 w-72 max-w-[80%] bg-white text-black shadow-xl z-[95] p-4 rounded-br-xl">
            <div className="flex items-center justify-between mb-2">
              <h2 className="font-semibold">Lịch sử chat</h2>
              <button onClick={onClose} className="text-sm text-gray-600 hover:text-black">
                ✕
              </button>
            </div>

            <ul className="space-y-2 max-h-64 overflow-y-auto">
              {historyItems?.length ? (
                historyItems.map((item, idx) => (
                  <li key={idx}>
                    <Link
                      href={item.href}
                      className="block px-2 py-1 rounded hover:bg-gray-100 text-sm"
                      onClick={onClose}
                    >
                      {item.name}
                    </Link>
                  </li>
                ))
              ) : (
                <li className="text-sm text-gray-500">Chưa có lịch sử</li>
              )}
            </ul>
          </div>
        </>
      )}
    </nav>
  );
};

export default NavbarMenu;
