"use client";
import { create } from "zustand";
import { persist } from "zustand/middleware";

/**
 * Lưu gọn: chỉ giữ mảng các modelId thay vì cả object.
 * Lưu message đơn giản: { id, role, content, modelId? }
 */
export const useChatStore = create(
  persist(
    (set) => ({
      messages: [],
      selectedModelIds: [],

      setMessages: (arr) => set({ messages: arr }),
      addMessage: (m) => set((s) => ({ messages: [...s.messages, m] })),
      clearMessages: () => set({ messages: [] }),

      setSelectedModelIds: (ids) => set({ selectedModelIds: Array.from(new Set(ids)) }),
    }),
    {
      name: "chat-store-v1",
      partialize: (s) => ({
        messages: s.messages,
        selectedModelIds: s.selectedModelIds,
      }),
    }
  )
);
